/* eslint-disable */
import React, { useRef, useState } from "react";
import { Link } from "react-router-dom";

import IndexNavbar from "components/Navbars/IndexNavbar.js";
import Footer from "components/Footers/Footer.js";
import HeroImage from "assets/img/bg1.png";
import BannerImage from "assets/img/banniere.png";
import NewsStack from "components/newsStack";
import PrettyCalendar from "components/calendar";
import ressourcesImg from "assets/img/ressourcesImg.png";
import News1 from "assets/img/mbaye.png";
import News2 from "assets/img/newdeal.jpg";
import News3 from "assets/img/sim.jpg";
import site1 from "assets/img/heritage.png";
import site2 from "assets/img/shirikia.png";
import site3 from "assets/img/accel.png";

import fatou from "assets/img/fatou.jpg";
import moussa from "assets/img/moussa.jpg";
import ndeye from "assets/img/ndeye.jpg";

import sankara from "assets/img/sankara.jpg";
export default function Index() {
  const [bannerOffset, setBannerOffset] = useState(0);
  const twoColRef = useRef(null);
  // Données de remplacement pour les sites (la partie gauche)
  const frequentSites = [
    { title: "Site 1 - Baobab", description: "Le héro du projet...", image: "assets/img/site1_baobab.png" },
    { title: "Site 2 - Data Map", description: "Plateforme donnée...", image: "assets/img/site2_datamap.png" },
    { title: "Site 3 - Shirikia", description: "Accélérateur...", image: "assets/img/site3_shirikia.png" },
  ];

  // Données de remplacement pour les profils (la partie droite)
  const profiles = [
    { name: "FATOU DIA", image: "assets/img/fatou_dia.jpg", color: "bg-gray-100/70" },
    { name: "MOUSSA FALL", image: "assets/img/moussa_fall.jpg", color: "bg-blue-100/70" },
    { name: "NDEYE SENE", image: "assets/img/ndeye_sene.jpg", color: "bg-gray-100/70" },
  ];

  return (
    <>
      <IndexNavbar fixed />

      {/* HERO */}
      <section
        className="relative mt-16 md:mt-20 h-screen max-h-860-px flex items-center"
        style={{
          backgroundImage: `linear-gradient(rgba(107, 20, 15, 0.65), rgba(107, 20, 15, 0.25)), url(${HeroImage})`,
          backgroundSize: "cover",
          backgroundPosition: "center 30%",
          backgroundRepeat: "no-repeat",
        }}
      >
        <div className="container mx-auto relative z-10 flex flex-wrap items-center">
          <div className="w-full lg:w-6/12 px-4">
            <h1 className="font-bold text-5xl md:text-7xl text-white leading-tight">
              Dalal ak jàamm,
            </h1>
            <p className="mt-6 text-2xl md:text-3xl font-light text-white max-w-xl">
              Nassour !
            </p>
          </div>
        </div>
      </section>

      {/* 2 colonnes : Calendrier + Actualités */}
      <section className="relative bg-white py-16">
        <div className="container mx-auto px-4">
          <div ref={twoColRef} className="flex flex-row items-start space-x-8">
            <div className="w-1/2 min-w-0">
              <h3 className="text-[#1c2b68] font-semibold text-xl mb-3">Un jour spécial pour ?</h3>
              <PrettyCalendar
                initialYear={2023}
                initialMonth={2}
                selectedDay={20}
                events={[
                  { date: "2023-02-20", label: "Anniversaire de Ousmane DIA" },
                  { date: "2023-02-16", label: "Réunion Produits" },
                ]}
              />
            </div>

            <div className="w-1/2 min-w-0">
              <h3 className="text-[#1c2b68] font-semibold text-xl mb-3">Actualités</h3>
              <NewsStack
                items={[
                  { img: News2, href: "#" },
                  { img: News3, href: "#" },
                  { img: News1, href: "#" },
                ]}
              />
            </div>
          </div>
        </div>
      </section>

      {/* Bannière — chevauche légèrement les actus */}
      <section
        className="relative w-full z-20"
        style={{
          marginTop: "-500px",
        }}
      >
        <img
          src={BannerImage}
          alt="Bannière"
          className="w-full h-[500px] object-cover rounded-lg shadow-lg"
        />
      </section>
      <section className="relative w-full bg-white py-16">
        <div className="w-full">
          <img
            src={ressourcesImg}
            alt="Nouvelle section"
            className="rounded-lg shadow-lg object-cover"
            style={{
              width: "45%",
              height: "33%",
              marginLeft: "0",
              marginTop: "-350px"
            }}
          />
        </div>
      </section>

      <div className="container mx-auto py-16 px-4">

        {/* Grille principale : 1/3 pour les liens à gauche, 2/3 pour les profils à droite */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">

          {/* COLONNE GAUCHE : SITES FREQUENTS */}
          <div className="lg:col-span-1">
            <h2 className="text-2xl font-semibold mb-8 text-gray-800 tracking-wider">SITES FREQUENTS</h2>

            <div className="space-y-6">
              {frequentSites.map((site, index) => (
                <a
                  key={index}
                  href="#"
                  className="block rounded-xl overflow-hidden shadow-lg hover:shadow-xl transition-shadow duration-300"
                >
                  {/* Placeholder pour les miniatures des sites web */}
                  {/* Les coins arrondis et l'ombre imitent le style de la miniature */}
                  <img
                    src={site.image}
                    alt={site.title}
                    className="w-full h-auto object-cover border border-gray-200 rounded-xl"
                  />
                </a>
              ))}
            </div>
          </div>

          {/* COLONNE DROITE : BIENVENUE / PROFILS */}
          <div className="lg:col-span-2">
            <h2 className="text-2xl font-semibold mb-8 text-blue-800 tracking-wider text-right">BIENVENUE !</h2>

            <div className="space-y-8">
              {profiles.map((profile, index) => (
                <div
                  key={index}
                  // Carte de Profil : coin très arrondi, ombre subtile, fond gris ou bleu très clair
                  className={`flex items-center p-6 rounded-[2rem] shadow-lg ${profile.color}`}
                  style={{
                    // Marge extérieure pour simuler la zone grise entre les cartes
                    boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05)'
                  }}
                >
                  {/* Image du Profil */}
                  <div className="w-40 h-40 flex-shrink-0 mr-6 rounded-xl overflow-hidden">
                    <img
                      src={profile.image}
                      alt={profile.name}
                      className="w-full h-full object-cover"
                    />
                  </div>

                  {/* Texte de Bienvenue */}
                  <div>
                    <h3 className="text-2xl font-bold text-gray-900 mb-1 tracking-wider">{profile.name}</h3>
                    <p className="font-serif text-lg text-gray-700 leading-relaxed">
                      Lorem Ipsum is simply dummy text of the printing and typesetting industry.
                    </p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>


      <section className="w-full bg-white py-20 flex justify-center items-center">
        <div className="flex flex-col md:flex-row items-center justify-center gap-8 md:gap-10">

          {/* === Photo Sankara === */}
          <div className="flex flex-col items-center md:items-start text-center md:text-left">
            <div className="w-[130px] h-[130px] md:w-[150px] md:h-[150px] rounded-lg overflow-hidden shadow">
              <img
                src={sankara}
                alt="Thomas Sankara"
                className="w-full h-full object-cover"
              />
            </div>
            <span className="mt-3 text-base md:text-lg font-semibold">
              Thomas Sankara
            </span>
          </div>

          {/* === Citation === */}
          <div className="bg-[#e6e6e6] rounded-md md:rounded-lg shadow-sm px-6 py-5 md:px-8 md:py-6 max-w-[600px]">
            <p className="font-semibold italic text-[#2b2b2b] text-[15px] md:text-[17px] leading-relaxed text-center">
              “Nous devons accepter de vivre africain. C’est la seule façon de vivre
              libre et de vivre digne.”
            </p>
          </div>
        </div>
      </section>






      {/* <Footer /> */}
    </>
  );
}
